class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)
        C = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = C[i - 1][j - 1] + C[i - 1][j]

        # Count values less than s grouped by their number of set bits.
        cnt = [0] * (n + 1)
        prefix_ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                remaining = n - i - 1
                for suffix_ones in range(remaining + 1):
                    cnt[prefix_ones + suffix_ones] += C[remaining][suffix_ones]
                prefix_ones += 1

        ans = 0
        for ones in range(1, n + 1):
            value = ones
            steps = 0
            while value != 1:
                value = value.bit_count()
                steps += 1
            # For a number with this many set bits, the first operation
            # produces `ones`; hence the total is one plus its reduction steps.
            if 1 + steps <= k:
                ans += cnt[ones]

        return ans % (10**9 + 7)

